+$rail: functions.to-rem(14px);
+$cell-pad: functions.to-rem(14px);
+$split-number: functions.to-rem(42px);
+$bar-h: 8px;
+
+@layer components {
+  .code {
+    --skeleton-row: calc(var(--font-size-lg) * 1.7);
+    --skeleton-number-width: calc(
+      var(--skeleton-digits) * 1ch + #{$cell-pad * 2}
+    );
+    --skeleton-number-ink: color-mix(
+      in srgb,
+      var(--color-text-1) 5%,
+      transparent
+    );
+    --skeleton-divider: var(--color-outline-1);
+    --skeleton-tint: 4%;
+    --skeleton-hatch-fill: color-mix(
+      in srgb,
+      var(--color-background) 70%,
+      var(--color-surface-1)
+    );
+    --skeleton-hatch: repeating-linear-gradient(
+      -45deg,
+      transparent 0 6px,
+      color-mix(in srgb, var(--color-outline-2) 55%, transparent) 6px 7px
+    );
+
+    position: relative;
+    display: grid;
+    block-size: calc(var(--skeleton-row) * var(--skeleton-span));
+
+    &[data-view="unified"] {
+      grid-template-columns:
+        var(--skeleton-number-width) var(--skeleton-number-width)
+        minmax(0, 1fr);
+      padding-inline-start: $rail;
+    }
+
+    &[data-view="split"] {
+      grid-template-columns:
+        $rail $split-number minmax(0, 1fr)
+        $rail $split-number minmax(0, 1fr);
+      background: linear-gradient(
+          var(--skeleton-divider),
+          var(--skeleton-divider)
+        )
+        no-repeat 50% 0 / 1px 100%;
+
+      > :nth-child(1) {
+        grid-column: 2;
+      }
+
+      > :nth-child(2) {
+        grid-column: 3;
+      }
+
+      > :nth-child(3) {
+        grid-column: 5;
+      }
+
+      > :nth-child(4) {
+        grid-column: 6;
+      }
+    }
+  }
+
+  [data-ink="neutral"] .code {
+    --skeleton-number-ink: color-mix(
+      in srgb,
+      var(--color-text-1) 4.5%,
+      transparent
+    );
+  }
+
+  [data-layer="shine"] .code {
+    --skeleton-number-ink: color-mix(
+      in srgb,
+      var(--color-text-1) 10%,
+      transparent
+    );
+    --skeleton-divider: transparent;
+    --skeleton-tint: 0%;
+    --skeleton-hatch-fill: transparent;
+    --skeleton-hatch: none;
+  }
+
+  .code[data-variant="added"],
+  .number[data-variant="added"] {
+    --skeleton-hue: var(--color-positive);
+    --skeleton-hue-number: 20%;
+  }
+
+  .code[data-variant="removed"],
+  .number[data-variant="removed"] {
+    --skeleton-hue: var(--color-negative);
+    --skeleton-hue-number: 22%;
+  }
+
+  .code[data-view="unified"]:is(
+      [data-variant="added"],
+      [data-variant="removed"]
+    ),
+  .code[data-view="split"]
+    > .number:is([data-variant="added"], [data-variant="removed"]) {
