+  .number {
+    position: relative;
+    min-inline-size: 0;
+
+    &:not([data-variant="empty"])::after {
+      position: absolute;
+      inset-block-start: calc((var(--skeleton-row) - #{$bar-h}) / 2);
+      inset-inline-start: $cell-pad;
+      inline-size: calc(var(--skeleton-digits) * 1ch);
