+    background-position:
+      calc(#{$cell-pad} + 1px)
+        calc(var(--skeleton-row) / 2 - #{$sign-stroke * 0.5}),
+      calc(#{$cell-pad} + 4px)
+        calc(var(--skeleton-row) / 2 - #{$sign-arm * 0.5});
+    background-size:
+      $sign-arm $sign-stroke,
+      $sign-stroke $sign-arm;
+
+    &::after,
+    .wrap {
+      background: color-mix(
+        in srgb,
+        var(--skeleton-hue) var(--skeleton-hue-ink),
+        transparent
+      );
+    }
+  }
+
+  .text[data-variant="removed"] {
+    background-size:
+      $sign-arm $sign-stroke,
+      0 0;
+  }
+
+  [data-view="split"]
+    > .text:is([data-variant="added"], [data-variant="removed"]) {
+    background-color: color-mix(
+      in srgb,
+      var(--skeleton-hue) var(--skeleton-tint),
+      transparent
+    );
+  }
+}
