+];
+
+/** Columns one indent level takes. */
+export const INDENT_STEP = 2;
+
+/** Where in its bucket a row's width falls, by row, a fixed cycle. */
+export const WIDTH_FRACTIONS = [
+  0.55, 0.9, 0.3, 0.75, 0.12, 0.65, 0.95, 0.45, 0.8, 0.2,
+];
+
