+    expect(plan.rows.map(describeRow)).toEqual([
+      "hunk",
+      "context",
+      "removed",
+      "added",
+      "added",
+      "context",
+      "context",
+      "hunk",
+      "context",
+      "added",
+      "context",
+      "expand",
+    ]);
